out <- "analysis/gamewell_sensitivity_2026-10-16"
input <- "analysis/gamewell_interval_dataset_2026-10-15/gamewell_daily_intervals.csv.gz"
primary_dir <- "analysis/gamewell_primary_model_2026-10-16"
for (p in c("lme4","lmerTest","clubSandwich")) if (!requireNamespace(p,quietly=TRUE)) stop(paste("Required package missing; no installation attempted:",p))
if (!file.exists(file.path(out,"PREFIT_COHORT_GATE.csv")) || !all(read.csv(file.path(out,"PREFIT_COHORT_GATE.csv"))$match)) stop("Prefit gate missing or failed; no fit run.")
if (!file.exists(file.path(primary_dir,"fixed_effects.csv")) || !file.exists(file.path(primary_dir,"cr2_conf_int.csv"))) stop("Required saved primary outputs missing; no fit run.")
d <- read.csv(gzfile(input),stringsAsFactors=FALSE,check.names=FALSE)
linked <- function(x) tolower(trimws(as.character(x))) %in% c("true","1","yes")
base_ok <- (linked(d$xbox_linked)|linked(d$nintendo_linked)) & !is.na(d$interval_duration_hours) & d$interval_duration_hours<=48 & !is.na(d$prior_affective_valence) & !is.na(d$later_affective_valence) & !is.na(d$recorded_linked_console_minutes_unique)
base <- d[base_ok,,drop=FALSE]
base$exposure_hours_raw <- base$recorded_linked_console_minutes_unique/60
base$exposure_minutes <- base$recorded_linked_console_minutes_unique
resfile <- file.path(out,"SENSITIVITY_FIT_RESULTS.csv")
summaryfile <- file.path(out,"SENSITIVITY_SUMMARY.csv")
errfile <- file.path(out,"FIT_ERRORS.csv")
if (any(file.exists(c(resfile,summaryfile,errfile,file.path(out,"LOO_AGGREGATE.csv"),file.path(out,"REPORT.md"),file.path(out,"sessionInfo.txt"))))) stop("Output exists; refusing overwrite.")
cols <- c("analysis_id","cohort_definition","n_intervals","n_participants","exposure_term","estimate","model_SE","model_df","model_CI_lower","model_CI_upper","CR2_SE","CR2_df","CR2_CI_lower","CR2_CI_upper","wider_CI_lower","wider_CI_upper","wider_source","exposure_within_SD","estimate_per_1SD_exposure","within_person_valence_SD","estimate_in_valence_SD_per_hour","estimate_per_1SD_valence","SESOI_scale","category","convergence_code","convergence_messages","singular_fit","random_intercept_SD","residual_SD","fit_status","fit_error","CR2_error")
write.csv(as.data.frame(setNames(replicate(length(cols),character(),simplify=FALSE),cols)),resfile,row.names=FALSE)
write.csv(data.frame(analysis_id=character(),error=character(),n_intervals=integer(),n_participants=integer()),errfile,row.names=FALSE)
append_df <- function(path,row){write.table(row,path,sep=",",row.names=FALSE,col.names=FALSE,append=TRUE,quote=TRUE,na="")}
add_derived <- function(x, exposure, type="hour") {
 x$participant <- factor(as.character(x$participant_id)); x$later_valence <- x$later_affective_valence
 x$exposure_raw <- exposure
 x$exposure_between <- ave(x$exposure_raw,x$participant,FUN=mean)
 x$exposure_within <- x$exposure_raw-x$exposure_between
 x$prior_between <- ave(x$prior_affective_valence,x$participant,FUN=mean)
 x$prior_within <- x$prior_affective_valence-x$prior_between
 x$log_interval_c <- log(x$interval_duration_hours)-mean(log(x$interval_duration_hours))
 x$exposure_within_sd <- stats::sd(x$exposure_within)
 x$valence_within_sd <- stats::sd(x$later_valence-ave(x$later_valence,x$participant,FUN=mean))
 x
}
catword <- function(cat) switch(cat,a="CI entirely within +/-SESOI",b="CI excludes zero and extends beyond SESOI",c="CI excludes zero but lies within SESOI",d="CI includes zero and extends beyond SESOI",NA_character_)
category <- function(lo,hi,threshold=.5){if(!is.finite(lo)||!is.finite(hi))return(NA_character_);if(lo > -threshold && hi < threshold)"a" else if((hi<0||lo>0)&&(lo < -threshold||hi > threshold))"b" else if((hi<0||lo>0)&&lo>=-threshold&&hi<=threshold)"c" else "d"}
summary_rows <- list(); srn <- 0L
add_summary <- function(x){srn<<-srn+1L;summary_rows[[srn]]<<-x}
run_fit <- function(id,def,x,random_slope=FALSE,category_mode="wider",threshold=.5,scale_mode="hour",record=TRUE){
 n<-nrow(x); np<-nlevels(x$participant); sd_x<-stats::sd(x$exposure_within); sd_y<-unique(x$valence_within_sd)[1]
 f <- if(random_slope) later_valence ~ exposure_within + exposure_between + prior_within + prior_between + log_interval_c + (1 + exposure_within | participant) else later_valence ~ exposure_within + exposure_between + prior_within + prior_between + log_interval_c + (1|participant)
 fit <- tryCatch(lmerTest::lmer(f,data=x,REML=TRUE),error=function(e)e)
 if(inherits(fit,"error")){ row<-as.data.frame(as.list(setNames(rep(NA,length(cols)),cols))); row$analysis_id<-id;row$cohort_definition<-def;row$n_intervals<-n;row$n_participants<-np;row$fit_status<-"error";row$fit_error<-conditionMessage(fit);append_df(resfile,row); append_df(errfile,data.frame(analysis_id=id,error=conditionMessage(fit),n_intervals=n,n_participants=np)); add_summary(data.frame(analysis_id=id,cohort_definition=def,n_intervals=n,n_participants=np,estimate=NA_real_,wider_CI_lower=NA_real_,wider_CI_upper=NA_real_,category=NA_character_,fit_status="error",singular_fit=NA,convergence_messages="",stringsAsFactors=FALSE)); return(list(ok=FALSE,error=conditionMessage(fit))) }
 cf<-summary(fit)$coefficients; i<-match("exposure_within",rownames(cf)); b<-unname(cf[i,"Estimate"]); se<-unname(cf[i,"Std. Error"]); df<-unname(cf[i,"df"]); modlo<-b-qt(.975,df)*se; modhi<-b+qt(.975,df)*se
 cr2err<-""; cr2se<-cr2df<-cr2lo<-cr2hi<-NA_real_
 cr<-tryCatch({ct<-as.data.frame(clubSandwich::coef_test(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));ci<-as.data.frame(clubSandwich::conf_int(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));list(ct=ct,ci=ci)},error=function(e){cr2err<<-conditionMessage(e);NULL})
 if(!is.null(cr)){termct<-if("Coef"%in%names(cr$ct)) as.character(cr$ct$Coef) else rownames(cr$ct); termci<-if("Coef"%in%names(cr$ci))as.character(cr$ci$Coef)else rownames(cr$ci); j<-match("exposure_within",termct); k<-match("exposure_within",termci); if(!is.na(j)&&!is.na(k)){secol<-intersect(c("SE","Std. Error"),names(cr$ct))[1];dfcol<-intersect(c("df_Satt","df"),names(cr$ct))[1];cr2se<-as.numeric(cr$ct[j,secol]);cr2df<-as.numeric(cr$ct[j,dfcol]);lcol<-intersect(c("CI_L","lower"),names(cr$ci))[1];ucol<-intersect(c("CI_U","upper"),names(cr$ci))[1];cr2lo<-as.numeric(cr$ci[k,lcol]);cr2hi<-as.numeric(cr$ci[k,ucol])}else cr2err<-"exposure_within term not found in CR2 output"}
 usecr<-is.finite(cr2lo)&&is.finite(cr2hi); widerlo<-if(usecr&&((cr2hi-cr2lo)>(modhi-modlo)))cr2lo else modlo; widerhi<-if(usecr&&((cr2hi-cr2lo)>(modhi-modlo)))cr2hi else modhi; source<-if(widerlo==cr2lo&&widerhi==cr2hi&&usecr)"CR2"else"model-based"
 cate<-if(category_mode=="none")NA_character_ else if(category_mode=="cr2"){if(usecr)category(cr2lo,cr2hi,threshold)else NA_character_}else if(scale_mode=="log_sd"){category(widerlo*sd_x,widerhi*sd_x,threshold)}else category(widerlo,widerhi,threshold)
 vc<-as.data.frame(lme4::VarCorr(fit)); ri<-vc$sdcor[vc$grp=="participant"&vc$var1=="(Intercept)"][1];rsd<-stats::sigma(fit); cc<-fit@optinfo$conv$opt; msgs<-fit@optinfo$conv$lme4$messages; msg<-if(length(msgs))paste(as.character(msgs),collapse=" | ")else if(length(cc)&&any(cc!=0))paste("optimizer code",paste(cc,collapse=","))else"none";sing<-lme4::isSingular(fit,tol=1e-4)
 row<-as.data.frame(as.list(setNames(rep(NA,length(cols)),cols)));row$analysis_id<-id;row$cohort_definition<-def;row$n_intervals<-n;row$n_participants<-np;row$exposure_term<-"exposure_within";row$estimate<-b;row$model_SE<-se;row$model_df<-df;row$model_CI_lower<-modlo;row$model_CI_upper<-modhi;row$CR2_SE<-cr2se;row$CR2_df<-cr2df;row$CR2_CI_lower<-cr2lo;row$CR2_CI_upper<-cr2hi;row$wider_CI_lower<-widerlo;row$wider_CI_upper<-widerhi;row$wider_source<-source;row$exposure_within_SD<-sd_x;row$estimate_per_1SD_exposure<-b*sd_x;row$within_person_valence_SD<-sd_y;row$estimate_in_valence_SD_per_hour<-if(scale_mode=="hour")b/sd_y else NA_real_;row$estimate_per_1SD_valence<-b*sd_x/sd_y;row$SESOI_scale<-threshold;row$category<-cate;row$convergence_code<-paste(cc,collapse=",");row$convergence_messages<-msg;row$singular_fit<-sing;row$random_intercept_SD<-ri;row$residual_SD<-rsd;row$fit_status<-"success";row$fit_error<-"";row$CR2_error<-cr2err; append_df(resfile,row)
 add_summary(data.frame(analysis_id=id,cohort_definition=def,n_intervals=n,n_participants=np,estimate=b,wider_CI_lower=widerlo,wider_CI_upper=widerhi,category=cate,fit_status="success",singular_fit=sing,convergence_messages=msg,stringsAsFactors=FALSE));list(ok=TRUE,fit=fit,category=cate,model_ci=c(modlo,modhi),cr2_ci=c(cr2lo,cr2hi),estimate=b)
}
# 7a: interval-length cohorts
for(h in c(30,36,72,Inf)){ tag<-if(is.infinite(h))"no_cutoff" else paste0(h,"h"); z<-base[is.infinite(h)|base$interval_duration_hours<=h,,drop=FALSE]; z<-add_derived(z,z$exposure_hours_raw);run_fit(paste0("7a_",tag),paste0("linked, complete valence endpoints; interval <= ",tag),z) }
# 7b(i): log(1 + minutes), scaled and judged per within-person SD
z<-base; rawlog<-log1p(z$exposure_minutes); z<-add_derived(z,rawlog); sdlog<-z$exposure_within_sd; r7bi<-run_fit("7b_i_log1p_minutes","primary cohort; exposure=log(1+minutes), CI scaled per 1 SD within-person exposure",z,threshold=.8326,scale_mode="log_sd")
# 7b(ii): cap hours at primary-cohort 99th percentile
cap<-as.numeric(quantile(base$exposure_hours_raw,.99,names=FALSE)); z<-base; capx<-pmin(z$exposure_hours_raw,cap); z<-add_derived(z,capx); r7bii<-run_fit("7b_ii_cap_99","primary cohort; hours capped at primary 99th percentile",z); write.csv(data.frame(primary_cohort_99th_percentile_exposure_hours=cap),file.path(out,"CAP_99_VALUE.csv"),row.names=FALSE)
# 7c: any-play indicator, centered within participant
z<-base; anyplay<-as.numeric(z$exposure_minutes>0); z<-add_derived(z,anyplay); run_fit("7c_any_play","primary cohort; any recorded play indicator",z,category_mode="none")
# 7d: platform-only subsets; only fit with >=100 people having >=2 intervals
for(group in c("xbox_only","nintendo_only","both_linked")){xl<-linked(base$xbox_linked);nl<-linked(base$nintendo_linked);sel<-if(group=="xbox_only")xl&!nl else if(group=="nintendo_only")nl&!xl else xl&nl; z<-base[sel,,drop=FALSE]; counts<-table(as.character(z$participant_id)); nrep<-sum(counts>=2); fitflag<-nrep>=100 && group!="both_linked"; if(fitflag){eligibleids<-names(counts[counts>=2]);z<-z[as.character(z$participant_id)%in%eligibleids,,drop=FALSE];z<-add_derived(z,z$exposure_hours_raw);run_fit(paste0("7d_",group),paste0(group," linkage subset; participants with >=2 eligible intervals"),z)}else{nint<-nrow(z);npart<-length(unique(z$participant_id));add_summary(data.frame(analysis_id=paste0("7d_",group),cohort_definition=paste0(group," linkage subset; counts only; fitting threshold unmet"),n_intervals=nint,n_participants=npart,estimate=NA_real_,wider_CI_lower=NA_real_,wider_CI_upper=NA_real_,category=NA_character_,fit_status=paste0("counts only; ",nrep," participants with >=2 intervals"),singular_fit=NA,convergence_messages="",stringsAsFactors=FALSE));append_df(errfile,data.frame(analysis_id=paste0("7d_",group),error=paste("Counts only;",nrep,"participants with >=2 intervals; threshold is 100"),n_intervals=nint,n_participants=npart))}}
# 7e: exclude participants with fewer than five intervals
counts<-table(as.character(base$participant_id)); ids<-names(counts[counts>=5]);z<-base[as.character(base$participant_id)%in%ids,,drop=FALSE];z<-add_derived(z,z$exposure_hours_raw);run_fit("7e_min5_intervals","primary cohort restricted to participants with >=5 eligible intervals",z)
# 7f: exclude intervals where either valence endpoint is zero
z<-base[base$prior_affective_valence!=0 & base$later_affective_valence!=0,,drop=FALSE];z<-add_derived(z,z$exposure_hours_raw);run_fit("7f_no_zero_valence","primary cohort excluding zero at either valence endpoint",z)
# 7g: random slope
z<-add_derived(base,base$exposure_hours_raw);r7g<-run_fit("7g_random_slope","primary cohort; random intercept and exposure_within slope",z,random_slope=TRUE)
# 7h: CR2-only category from saved primary model, no new fit
pfx<-read.csv(file.path(primary_dir,"fixed_effects.csv"),stringsAsFactors=FALSE);pci<-read.csv(file.path(primary_dir,"cr2_conf_int.csv"),stringsAsFactors=FALSE);pi<-match("exposure_within",pfx$term);pj<-match("exposure_within",pci$term);pcat<-category(as.numeric(pci$CI_L[pj]),as.numeric(pci$CI_U[pj]),.5); add_summary(data.frame(analysis_id="7h_CR2_primary_no_refit",cohort_definition="saved primary fit; CR2 CI only",n_intervals=5076L,n_participants=371L,estimate=as.numeric(pfx$estimate[pi]),wider_CI_lower=as.numeric(pci$CI_L[pj]),wider_CI_upper=as.numeric(pci$CI_U[pj]),category=pcat,fit_status="no new fit; saved primary output",singular_fit=NA,convergence_messages="",stringsAsFactors=FALSE))
# 7i: leave-one-participant-out, aggregate only
zall<-add_derived(base,base$exposure_hours_raw);allids<-levels(zall$participant);loo_est<-numeric();loo_cat<-character();loo_errors<-character();for(ii in seq_along(allids)){zz<-zall[as.character(zall$participant)!=allids[ii],,drop=FALSE];zz<-add_derived(zz,zz$exposure_hours_raw);ff<-tryCatch(lmerTest::lmer(later_valence~exposure_within+exposure_between+prior_within+prior_between+log_interval_c+(1|participant),data=zz,REML=TRUE),error=function(e)e);if(inherits(ff,"error")){loo_errors<-c(loo_errors,conditionMessage(ff));next};cf<-summary(ff)$coefficients;bi<-match("exposure_within",rownames(cf));bb<-unname(cf[bi,"Estimate"]);ss<-unname(cf[bi,"Std. Error"]);dd<-unname(cf[bi,"df"]);lo<-bb-qt(.975,dd)*ss;hi<-bb+qt(.975,dd)*ss;loo_est<-c(loo_est,bb);loo_cat<-c(loo_cat,category(lo,hi,.5))}
if(length(loo_est)){qq<-quantile(loo_est,c(0,.025,.5,.975,1),names=FALSE);different<-sum(loo_cat!="a",na.rm=TRUE);loo<-data.frame(requested_refits=length(allids),successful_refits=length(loo_est),failed_refits=length(loo_errors),estimate_min=qq[1],estimate_q025=qq[2],estimate_median=qq[3],estimate_q975=qq[4],estimate_max=qq[5],model_based_category_different_from_primary=sum(loo_cat!="a",na.rm=TRUE),failure_messages=if(length(loo_errors))paste(unique(loo_errors),collapse=" | ")else"none");write.csv(loo,file.path(out,"LOO_AGGREGATE.csv"),row.names=FALSE);add_summary(data.frame(analysis_id="7i_LOO_aggregate",cohort_definition="371 leave-one-participant-out refits; aggregate only",n_intervals=NA_integer_,n_participants=371L,estimate=median(loo_est),wider_CI_lower=NA_real_,wider_CI_upper=NA_real_,category=NA_character_,fit_status=paste0(length(loo_est)," successful; ",length(loo_errors)," failed"),singular_fit=NA,convergence_messages="LOO category differs from primary: see aggregate",stringsAsFactors=FALSE))}else{write.csv(data.frame(requested_refits=length(allids),successful_refits=0,failed_refits=length(loo_errors),failure_messages=paste(unique(loo_errors),collapse=" | ")),file.path(out,"LOO_AGGREGATE.csv"),row.names=FALSE)}
# Save grouped summary and derive robustness label by code
summ<-do.call(rbind,summary_rows);write.csv(summ,summaryfile,row.names=FALSE)
required_ids<-c(paste0("7a_",c("30h","36h","72h","no_cutoff")),"7b_i_log1p_minutes","7b_ii_cap_99","7e_min5_intervals","7f_no_zero_valence","7g_random_slope","7h_CR2_primary_no_refit"); req<-summ[match(required_ids,summ$analysis_id),];robust<-all(!is.na(req$category)&req$category=="a")&&nrow(req)==length(required_ids);robust_label<-if(robust)"robust under all required prespecified sensitivities"else"sensitive to one or more named analytic choices or unavailable fits"
report<-c("# GameWell prespecified sensitivity analyses","","## Gate","", "Six SHA-256 checks passed for Plan v1, Addenda 1–4, and the interval dataset. The primary cohort gate reproduced 5,076 intervals, 371 participants, and 171 participants with exposure variation. The gate outputs are PREFIT_HASH_CHECKS.csv and PREFIT_COHORT_GATE.csv.","","## Results","","All fitted specifications use the Plan v1 fixed-effects structure, REML, and the default optimizer, except 7g which adds the prespecified random slope. Cohort-specific means and centered variables were recomputed within each cohort. 7h uses saved primary results and adds no fit. Estimates describe associations with recorded linked-console play.","","Analysis | Cohort | N intervals | N participants | Estimate | Wider CI | Category | Fit/singularity","---|---|---:|---:|---:|---|---|---")
for(i in seq_len(nrow(summ))){a<-summ[i,];ci<-if(is.finite(a$wider_CI_lower)&&is.finite(a$wider_CI_upper))sprintf("[%.4f, %.4f]",a$wider_CI_lower,a$wider_CI_upper)else"not available";es<-if(is.finite(a$estimate))sprintf("%.6f",a$estimate)else"not fitted";ns<-if(is.finite(a$n_intervals))as.character(a$n_intervals)else"aggregate";np<-if(is.finite(a$n_participants))as.character(a$n_participants)else"aggregate";sg<-if(is.na(a$singular_fit))"n/a"else as.character(a$singular_fit);report<-c(report,sprintf("%s | %s | %s | %s | %s | %s | %s | %s; %s",a$analysis_id,a$cohort_definition,ns,np,es,ci,ifelse(is.na(a$category),"none",a$category),a$fit_status,sg))}
report<-c(report,"","### Robustness label","",robust_label,"","The label is computed as robust only when 7a (four cohorts), 7b (both versions), 7e, 7f, 7g, and 7h all have category (a). Any unavailable or failed required fit means the criterion is not met.","","### Additional prespecified summaries","","7b(i) is judged after scaling its wider CI by the cohort-specific SD of within-person log(1 + minutes), against +/-0.8326 valence points per SD. 7b(ii) uses the primary-cohort 99th percentile cap recorded in CAP_99_VALUE.csv. 7c is descriptive and has no category. 7d fits only qualifying platform subsets; otherwise it reports counts. 7i results are in LOO_AGGREGATE.csv and contain no participant identifiers.","","## Fit errors","",if(file.info(errfile)$size>nchar("\"analysis_id\",\"error\",\"n_intervals\",\"n_participants\"\n"))"See FIT_ERRORS.csv for exact fit errors or counts-only 7d exclusions."else"No fit errors or counts-only exclusions were recorded.","","## Limitations","","- Coverage: zero recorded sessions are not distinguishable from missing capture at the interval level under the source coverage assumption.","- Nintendo telemetry covers first-party titles only; other platforms and titles are outside recorded exposure.","- Valence has ceiling compression and heterogeneous residual spread in the primary fit; the primary fit is singular, so repeated-cohort random-effect interpretation is limited.","- The source data are observational. Results are associational and do not establish causal effects.","- The exposure represents recorded linked-console play, not total gaming; telemetry completeness is uncertain.","","## Execution record","","No primary model was refitted. Sensitivity fits listed in Addendum 4 were run once each, except 7i which contains the prespecified leave-one-participant-out fits; errors were recorded without substitute specifications. No secondary life-satisfaction analysis was run. No participant IDs or study data rows were written to outputs.")
writeLines(report,file.path(out,"REPORT.md"),useBytes=TRUE);writeLines(capture.output(sessionInfo()),file.path(out,"sessionInfo.txt"),useBytes=TRUE);cat("Sensitivity analyses complete; aggregate outputs saved.\n")